delivery.css:
:host {
  display: block;
  color: #352c31;
  font-family: "Noto Serif SC", "Source Han Serif SC", "Microsoft YaHei", serif;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

button,
textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

.gal-stage {
  --character-scale: 1;
  --dialogue-font-size: clamp(17px, 2vw, 27px);
  position: relative;
  width: min(100%, 1100px);
  height: min(calc(100dvh - 66px), 619px);
  min-height: 540px;
  margin: 0 auto;
  overflow: hidden;
  border-radius: 8px;
  background: #050405;
  box-shadow: 0 6px 24px rgb(0 0 0 / 45%);
  user-select: none;
}

.gal-background,
.gal-vignette,
.gal-character-layer,
.gal-cg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.gal-background {
  object-fit: cover;
}

.gal-vignette {
  z-index: 1;
  pointer-events: none;
  background: linear-gradient(90deg, rgb(0 0 0 / 10%), transparent 30%, transparent 70%, rgb(0 0 0 / 12%));
}

.gal-character-layer {
  z-index: 2;
  pointer-events: none;
}

.gal-character {
  position: absolute;
  top: 7%;
  height: 195%;
  max-width: none;
  object-fit: contain;
  object-position: center 18%;
  filter: drop-shadow(0 0 10px rgb(0 0 0 / 42%));
  transform-origin: 50% 15%;
  transition: filter 180ms ease, opacity 180ms ease, transform 280ms ease;
}

.gal-character-left {
  left: 17%;
  transform: translateX(-50%) scale(var(--character-scale));
}

.gal-character-center {
  left: 50%;
  transform: translateX(-50%) scale(var(--character-scale));
}

.gal-character-right {
  left: 83%;
  transform: translateX(-50%) scaleX(-1) scale(var(--character-scale));
}

.gal-character.dimmed {
  filter: brightness(.45) grayscale(.15) drop-shadow(0 0 10px rgb(0 0 0 / 45%));
}

.gal-character.near.gal-character-left,
.gal-character.near.gal-character-center {
  transform: translateX(-50%) scale(calc(var(--character-scale) * 1.08));
}

.gal-character.near.gal-character-right {
  transform: translateX(-50%) scaleX(-1) scale(calc(var(--character-scale) * 1.08));
}

.gal-character.away.gal-character-left,
.gal-character.away.gal-character-center {
  transform: translateX(-50%) scale(calc(var(--character-scale) * .92));
}

.gal-character.away.gal-character-right {
  transform: translateX(-50%) scaleX(-1) scale(calc(var(--character-scale) * .92));
}

.gal-character.motion-shake {
  animation: gal-shake .5s ease-in-out;
}

.gal-character.motion-up {
  animation: gal-jump-up .32s ease-out;
}

.gal-character.motion-down {
  animation: gal-jump-down .32s ease-out;
}

@keyframes gal-shake {
  0%, 100% { margin-left: 0; }
  25% { margin-left: -8px; }
  75% { margin-left: 8px; }
}

@keyframes gal-jump-up {
  0%, 100% { margin-top: 0; }
  50% { margin-top: -22px; }
}

@keyframes gal-jump-down {
  0%, 100% { margin-top: 0; }
  50% { margin-top: 12px; }
}

.gal-cg {
  z-index: 3;
  background: #000;
}

.gal-cg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.gal-location {
  position: absolute;
  z-index: 8;
  top: 18px;
  right: 18px;
  padding: 7px 17px;
  border: 2px solid rgb(255 154 158 / 60%);
  border-radius: 999px;
  background: rgb(255 255 255 / 86%);
  box-shadow: 0 4px 15px rgb(0 0 0 / 15%);
  font-weight: 700;
  letter-spacing: .08em;
}

.gal-dialogue {
  position: absolute;
  z-index: 5;
  right: 0;
  bottom: 30px;
  left: 0;
  min-height: 31%;
  max-height: 46%;
  padding: 26px 6% 32px;
  overflow-y: auto;
  border-top: 2px solid rgb(255 255 255 / 82%);
  background: linear-gradient(180deg, rgb(255 255 255 / 30%), rgb(255 255 255 / 95%) 22%);
  backdrop-filter: blur(3px);
  box-shadow: 0 -4px 16px rgb(0 0 0 / 7%);
  transition: opacity 180ms ease;
}

.gal-speaker {
  position: absolute;
  top: -1px;
  left: 5%;
  padding: 5px 20px;
  border: 2px solid rgb(255 255 255 / 90%);
  border-radius: 999px;
  background: linear-gradient(135deg, #ff9a9e, #fecfef);
  box-shadow: 0 4px 12px rgb(255 154 158 / 40%);
  color: #5c4b51;
  font: 900 15px/1.3 system-ui, sans-serif;
  letter-spacing: .14em;
}

.gal-text {
  min-height: 2.7em;
  margin: 8px 0 0;
  color: #3a2c30;
  font-size: var(--dialogue-font-size);
  font-weight: 600;
  line-height: 1.8;
  letter-spacing: .04em;
  white-space: pre-wrap;
  text-shadow: 1px 1px 0 rgb(255 255 255 / 90%);
}

.gal-page {
  position: absolute;
  right: 16px;
  bottom: 7px;
  color: #936d78;
  font: 12px/1.2 system-ui, sans-serif;
}

.gal-controls {
  position: absolute;
  z-index: 10;
  right: 0;
  bottom: 0;
  left: 0;
  height: 30px;
  display: flex;
  background: linear-gradient(90deg, rgb(255 182 193 / 96%), rgb(255 192 203 / 96%));
  box-shadow: 0 -2px 10px rgb(255 105 135 / 15%);
}

.gal-controls button {
  flex: 1;
  min-width: 0;
  padding: 0 4px;
  overflow: hidden;
  border: 0;
  border-right: 1px solid rgb(255 255 255 / 42%);
  background: transparent;
  color: #fff;
  font: 700 clamp(10px, 1.25vw, 14px)/1 system-ui, sans-serif;
  text-overflow: ellipsis;
  text-shadow: 0 1px 2px rgb(0 0 0 / 15%);
  white-space: nowrap;
}

.gal-controls button:hover,
.gal-controls button.active {
  background: rgb(255 105 135 / 72%);
}

.gal-controls button:disabled,
.gal-input-actions button:disabled,
.gal-choice-list button:disabled {
  cursor: default;
  opacity: .45;
}

button:focus-visible,
textarea:focus-visible {
  outline: 2px solid #fff;
  outline-offset: -3px;
}

.gal-status {
  position: absolute;
  z-index: 20;
  top: 50%;
  left: 50%;
  width: min(92%, 720px);
  max-height: 86%;
  padding: 18px;
  overflow: auto;
  border: 2px solid rgb(255 182 193 / 65%);
  border-radius: 14px;
  background: rgb(255 255 255 / 96%);
  box-shadow: 0 14px 50px rgb(0 0 0 / 38%);
  transform: translate(-50%, -50%);
}

.gal-display-panel {
  position: absolute;
  z-index: 20;
  top: 50%;
  left: 50%;
  width: min(86%, 340px);
  padding: 20px;
  border: 2px solid rgb(255 182 193 / 70%);
  border-radius: 14px;
  background: rgb(255 255 255 / 96%);
  box-shadow: 0 14px 50px rgb(0 0 0 / 38%);
  transform: translate(-50%, -50%);
  font-family: system-ui, sans-serif;
}

.gal-display-panel header {
  margin-bottom: 14px;
  color: #ff758c;
}

.gal-display-panel label {
  display: grid;
  grid-template-columns: 80px 1fr;
  align-items: center;
  gap: 10px;
  margin: 14px 0;
  color: #78545d;
  font-weight: 700;
}

.gal-display-panel input {
  width: 100%;
  accent-color: #ff758c;
}

.gal-display-panel button,
.gal-gallery header button,
.gal-gallery-viewer button {
  padding: 7px 14px;
  border: 0;
  border-radius: 6px;
  background: #f4bdc8;
  color: #63464e;
}

.gal-gallery {
  position: absolute;
  z-index: 21;
  inset: 4%;
  padding: 18px;
  overflow: hidden;
  border-radius: 14px;
  background: rgb(20 13 17 / 94%);
  box-shadow: 0 14px 50px rgb(0 0 0 / 48%);
}

.gal-gallery header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
  color: #fff;
  font-family: system-ui, sans-serif;
}

.gal-gallery-grid {
  height: calc(100% - 48px);
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 12px;
  overflow-y: auto;
}

.gal-gallery-grid > div {
  position: relative;
  min-height: 112px;
  overflow: hidden;
  border: 2px solid rgb(255 255 255 / 14%);
  border-radius: 8px;
  background: #080608;
}

.gal-gallery-grid img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.gal-gallery-grid button {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: linear-gradient(transparent 50%, rgb(0 0 0 / 86%));
  color: #fff;
  font: 700 12px/1.4 system-ui, sans-serif;
  text-align: center;
  padding: 62px 6px 5px;
}

.gal-gallery-grid button:disabled {
  background: rgb(10 8 10 / 84%);
  color: rgb(255 255 255 / 45%);
}

.gal-gallery-viewer {
  position: absolute;
  z-index: 25;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgb(0 0 0 / 92%);
}

.gal-gallery-viewer img {
  max-width: 94%;
  max-height: 92%;
  object-fit: contain;
}

.gal-gallery-viewer button {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 36px;
  height: 36px;
  padding: 0;
  border-radius: 50%;
  font-size: 22px;
}

.gal-status header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
  color: #ff758c;
  font-family: system-ui, sans-serif;
}

.gal-status header button {
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: 50%;
  background: #ffe1e7;
  color: #7d4b57;
}

.gal-status-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.gal-status-grid section + section {
  padding-left: 16px;
  border-left: 1px dashed #efb6c2;
}

.gal-status label,
.gal-status-label {
  display: flex;
  justify-content: space-between;
  margin: 8px 0;
  color: #78545d;
  font: 700 13px/1.5 system-ui, sans-serif;
}

.gal-status progress {
  width: 100%;
  accent-color: #ff758c;
}

.gal-melody {
  color: #ff758c;
  font-weight: 700;
}

.gal-voice {
  padding: 10px;
  border-radius: 8px;
  background: #fff2f5;
  font-size: 13px;
  line-height: 1.6;
}

.gal-status dl,
.gal-status dd {
  margin: 0;
}

.gal-status dl div {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 0;
  border-bottom: 1px solid #f6dce2;
  font: 12px/1.5 system-ui, sans-serif;
}

.gal-status dd {
  text-align: right;
}

.gal-turn-delta {
  color: #a04d62;
  font: 12px/1.5 system-ui, sans-serif;
}

.gal-choice-list {
  position: absolute;
  z-index: 12;
  top: 48%;
  left: 50%;
  width: min(82%, 400px);
  display: grid;
  gap: 10px;
  transform: translate(-50%, -50%);
}

.gal-choice-list button {
  padding: 11px 18px;
  border: 2px solid #ffc3d0;
  border-radius: 8px;
  background: rgb(255 255 255 / 95%);
  box-shadow: 0 4px 12px rgb(0 0 0 / 22%);
  color: #5c4b51;
  font-weight: 700;
}

.gal-choice-list button:hover {
  border-color: #ff758c;
  color: #db5973;
  transform: scale(1.025);
}

.gal-input-panel {
  position: absolute;
  z-index: 22;
  right: 5%;
  bottom: 85px;
  width: min(90%, 460px);
  padding: 18px;
  border: 2px solid #f6b5c2;
  border-radius: 12px;
  background: rgb(255 249 250 / 97%);
  box-shadow: 0 10px 42px rgb(0 0 0 / 38%);
  font-family: system-ui, sans-serif;
}

.gal-input-panel label {
  display: block;
  margin-bottom: 9px;
  color: #78545d;
  font-weight: 700;
}

.gal-input-panel textarea {
  width: 100%;
  height: 92px;
  resize: vertical;
  padding: 10px;
  border: 1px solid #d69eaa;
  border-radius: 6px;
  background: #fff;
  color: #352c31;
  user-select: text;
}

.gal-input-actions {
  display: flex;
  gap: 8px;
  margin-top: 10px;
}

.gal-input-actions button {
  padding: 8px 18px;
  border: 0;
  border-radius: 6px;
  background: #f4bdc8;
  color: #63464e;
}

.gal-feedback {
  position: absolute;
  z-index: 24;
  top: 14px;
  left: 14px;
  max-width: 65%;
  margin: 0;
  padding: 7px 11px;
  border-radius: 6px;
  background: rgb(76 29 42 / 85%);
  color: #fff;
  font: 12px/1.45 system-ui, sans-serif;
}

.gal-feedback:empty {
  display: none;
}

.gal-stage.dialogue-hidden .gal-dialogue,
.gal-stage.dialogue-hidden .gal-controls {
  opacity: 0;
  pointer-events: none;
}

.gal-stage.display-small {
  --dialogue-font-size: clamp(14px, 1.6vw, 20px);
  --character-scale: .88;
}

.gal-stage.display-large {
  --dialogue-font-size: clamp(20px, 2.4vw, 31px);
  --character-scale: 1.12;
}

.gal-stage.font-70 { --dialogue-font-size: clamp(12px, 1.4vw, 19px); }
.gal-stage.font-80 { --dialogue-font-size: clamp(14px, 1.6vw, 22px); }
.gal-stage.font-90 { --dialogue-font-size: clamp(16px, 1.8vw, 24px); }
.gal-stage.font-100 { --dialogue-font-size: clamp(17px, 2vw, 27px); }
.gal-stage.font-110 { --dialogue-font-size: clamp(18px, 2.2vw, 29px); }
.gal-stage.font-120 { --dialogue-font-size: clamp(20px, 2.4vw, 32px); }
.gal-stage.font-130 { --dialogue-font-size: clamp(21px, 2.6vw, 35px); }
.gal-stage.font-140 { --dialogue-font-size: clamp(23px, 2.8vw, 38px); }
.gal-stage.font-150 { --dialogue-font-size: clamp(25px, 3vw, 41px); }
.gal-stage.character-60 { --character-scale: .6; }
.gal-stage.character-70 { --character-scale: .7; }
.gal-stage.character-80 { --character-scale: .8; }
.gal-stage.character-90 { --character-scale: .9; }
.gal-stage.character-100 { --character-scale: 1; }
.gal-stage.character-110 { --character-scale: 1.1; }
.gal-stage.character-120 { --character-scale: 1.2; }
.gal-stage.character-130 { --character-scale: 1.3; }
.gal-stage.character-140 { --character-scale: 1.4; }

.gal-stage.effect-flash::after,
.gal-stage.effect-black::after {
  content: "";
  position: absolute;
  z-index: 30;
  inset: 0;
  pointer-events: none;
}

.gal-stage.effect-flash::after {
  animation: gal-flash .25s ease-out;
  background: #fff;
}

.gal-stage.effect-black::after {
  background: #000;
  opacity: 1;
}

@keyframes gal-flash {
  from { opacity: .85; }
  to { opacity: 0; }
}

@media (max-width: 720px) {
  .gal-stage {
    height: calc(100dvh - 116px);
    min-height: 520px;
    border-radius: 0;
  }

  .gal-character {
    top: -2%;
    height: 235%;
  }

  .gal-character-left { left: 24%; }
  .gal-character-right { left: 76%; }

  .gal-dialogue {
    min-height: 36%;
    max-height: 51%;
    padding: 22px 4% 31px;
  }

  .gal-status-grid {
    grid-template-columns: 1fr;
  }

  .gal-status-grid section + section {
    padding-top: 10px;
    padding-left: 0;
    border-top: 1px dashed #efb6c2;
    border-left: 0;
  }

  .gal-controls button {
    font-size: 10px;
  }
}
